  5444  static int
  5445  md_is_setext_underline(MD_CTX* ctx, OFF beg, OFF* p_end, unsigned* p_level)
  5446  {
  5447      OFF off = beg + 1;
  5448
  5449      while(off < ctx->size  &&  CH(off) == CH(beg))
  5450          off++;
  5451
  5452      /* Optionally, space(s) or tabs can follow. */
  5453      while(off < ctx->size  &&  ISBLANK(off))
  5454          off++;
  5455
  5456      /* But nothing more is allowed on the line. */
  5457      if(off < ctx->size  &&  !ISNEWLINE(off))
  5458          return FALSE;
  5459
  5460      *p_level = (CH(beg) == _T('=') ? 1 : 2);
  5461      *p_end = off;
  5462      return TRUE;
  5463  }
