  5465  static int
  5466  md_is_table_underline(MD_CTX* ctx, OFF beg, OFF* p_end, unsigned* p_col_count)
  5467  {
  5468      OFF off = beg;
  5469      int found_pipe = FALSE;
  5470      unsigned col_count = 0;
  5471
  5472      if(off < ctx->size  &&  CH(off) == _T('|')) {
  5473          found_pipe = TRUE;
  5474          off++;
  5475          while(off < ctx->size  &&  ISWHITESPACE(off))
  5476              off++;
  5477      }
  5478
  5479      while(1) {
  5480          int delimited = FALSE;
  5481
  5482          /* Cell underline ("-----", ":----", "----:" or ":----:") */
  5483          if(off < ctx->size  &&  CH(off) == _T(':'))
  5484              off++;
  5485          if(off >= ctx->size  ||  CH(off) != _T('-'))
  5486              return FALSE;
  5487          while(off < ctx->size  &&  CH(off) == _T('-'))
  5488              off++;
  5489          if(off < ctx->size  &&  CH(off) == _T(':'))
  5490              off++;
  5491
  5492          col_count++;
  5493          if(col_count > TABLE_MAXCOLCOUNT) {
  5494              MD_LOG("Suppressing table (column_count >" STRINGIZE(TABLE_MAXCOLCOUNT) ")");
  5495              return FALSE;
  5496          }
  5497
  5498          /* Pipe delimiter (optional at the end of line). */
  5499          while(off < ctx->size  &&  ISWHITESPACE(off))
  5500              off++;
  5501          if(off < ctx->size  &&  CH(off) == _T('|')) {
  5502              delimited = TRUE;
  5503              found_pipe =  TRUE;
  5504              off++;
  5505              while(off < ctx->size  &&  ISWHITESPACE(off))
  5506                  off++;
  5507          }
  5508
  5509          /* Success, if we reach end of line. */
  5510          if(off >= ctx->size  ||  ISNEWLINE(off))
  5511              break;
  5512
  5513          if(!delimited)
  5514              return FALSE;
  5515      }
  5516
  5517      if(!found_pipe)
  5518          return FALSE;
  5519
  5520      *p_end = off;
  5521      *p_col_count = col_count;
  5522      return TRUE;
  5523  }
