  5525  static int
  5526  md_is_opening_code_fence(MD_CTX* ctx, OFF beg, OFF* p_end)
  5527  {
  5528      OFF off = beg;
  5529
  5530      while(off < ctx->size && CH(off) == CH(beg))
  5531          off++;
  5532
  5533      /* Fence must have at least three characters. */
  5534      if(off - beg < 3)
  5535          return FALSE;
  5536
  5537      ctx->code_fence_length = off - beg;
  5538
  5539      /* Optionally, space(s) can follow. */
  5540      while(off < ctx->size  &&  CH(off) == _T(' '))
  5541          off++;
  5542
  5543      /* Optionally, an info string can follow. */
  5544      while(off < ctx->size  &&  !ISNEWLINE(off)) {
  5545          /* Backtick-based fence must not contain '`' in the info string. */
  5546          if(CH(beg) == _T('`')  &&  CH(off) == _T('`'))
  5547              return FALSE;
  5548          off++;
  5549      }
  5550
  5551      *p_end = off;
  5552      return TRUE;
  5553  }
