  5555  static int
  5556  md_is_closing_code_fence(MD_CTX* ctx, CHAR ch, OFF beg, OFF* p_end)
  5557  {
  5558      OFF off = beg;
  5559      int ret = FALSE;
  5560
  5561      /* Closing fence must have at least the same length and use same char as
  5562       * opening one. */
  5563      while(off < ctx->size  &&  CH(off) == ch)
  5564          off++;
  5565      if(off - beg < ctx->code_fence_length)
  5566          goto out;
  5567
  5568      /* Optionally, space(s) can follow */
  5569      while(off < ctx->size  &&  ISANYOF2(off, _T(' '), _T('\t')))
  5570          off++;
  5571
  5572      /* But nothing more is allowed on the line. */
  5573      if(off < ctx->size  &&  !ISNEWLINE(off))
  5574          goto out;
  5575
  5576      ret = TRUE;
  5577
  5578  out:
  5579      /* Note we set *p_end even on failure: If we are not closing fence, caller
  5580       * would eat the line anyway without any parsing. */
  5581      *p_end = off;
  5582      return ret;
  5583  }
